begin;




update public.planta pl set ativa = false from public.obra o join public.pavimento p on p.obra_id = o.id and p.codigo = 'terreo' where o.slug = 'hto' and pl.pavimento_id = p.id and pl.revisao <> 'R05' and pl.ativa;
